Let's design a Zero Trust access policy using pseudocode:

```python
def evaluate_access_request(user, device, network, resource):
    """Zero Trust access evaluation engine."""

    # Initialize risk score
    risk_score = 0
    conditions = []

    # === PILLAR 1: Identity ===
    if not user.authenticated:
        return AccessDecision.DENY, "User not authenticated"

    if not user.mfa_completed:
        return AccessDecision.DENY, "MFA required"

    if user.risk_level == 'high':
        risk_score += 40
        conditions.append('High-risk identity')
    elif user.risk_level == 'medium':
        risk_score += 20
        conditions.append('Medium-risk identity')

    # Check role-based access
    if resource.required_role not in user.roles:
        return AccessDecision.DENY, f"Role {resource.required_role} required"

    # === PILLAR 2: Device ===
    if not device.registered:
        risk_score += 30
        conditions.append('Unregistered device')

    if not device.compliant:
        risk_score += 25
        conditions.append('Non-compliant device')

    if not device.edr_running:
        risk_score += 20
        conditions.append('No EDR agent')

    if device.os_version not in approved_os_versions:
        risk_score += 15
        conditions.append('Outdated OS')

    # === PILLAR 3: Network ===
    if network.location == 'untrusted':
        risk_score += 30
        conditions.append('Untrusted network')
    elif network.location == 'corporate':
        risk_score += 5  # Even corporate networks aren't fully trusted
    elif network.location == 'known_safe':
        risk_score += 0

    if not network.encrypted:
        risk_score += 15
        conditions.append('Unencrypted connection')

    # === PILLAR 4: Application ===
    if resource.sensitivity == 'critical' and not device.compliant:
        return AccessDecision.DENY, "Critical resources require compliant device"

    # === PILLAR 5: Data ===
    if resource.data_classification == 'restricted':
        if user.clearance_level < resource.required_clearance:
            return AccessDecision.DENY, "Insufficient clearance for restricted data"
        if network.location != 'corporate':
            return AccessDecision.DENY, "Restricted data requires corporate network"

    # === Risk-based Decision ===
    if risk_score >= 50:
        return AccessDecision.STEP_UP, f"Step-up authentication required: {conditions}"
    elif risk_score >= 30:
        return AccessDecision.LIMITED, f"Limited access granted: {conditions}"
    else:
        return AccessDecision.ALLOW, "Full access granted"


class AccessDecision:
    ALLOW = "allow"
    DENY = "deny"
    STEP_UP = "step_up"    # Require additional authentication
    LIMITED = "limited"    # Reduced permissions
```

**Analysis Questions:**
1. Why does the corporate network still add a small risk score (5 points)?
2. What happens if a user has high identity risk but a compliant device?
3. Why is step-up authentication triggered instead of outright denial at risk score 50?
4. How would you modify this for a developer who needs access to production systems?
